import{_ as i,a0 as o,w as a,s as l,ao as c,I as r,x as e,a1 as n,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"Linux有問必答：如何為CentOS 7配置靜態IP地址 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何為CentOS 7配置靜態IP地址 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何為CentOS 7配置靜態IP地址 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何為CentOS 7配置靜態IP地址 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140925 Linux FAQs with Answers--How to configure a static IP address on CentOS 7","title":"Linux有問必答：如何為CentOS 7配置靜態IP地址","tag":"201410","desc":""},"relativePath":"201410/20140925 Linux FAQs with Answers--How to configure a static IP address on CentOS 7.md","filePath":"[post].md"}'),d={name:"201410/20140925 Linux FAQs with Answers--How to configure a static IP address on CentOS 7.md"};function m(f,t,u,g,C,x){const s=o("Link");return a(),l("div",null,[t[11]||(t[11]=c(`<h1 id="linux有問必答-如何為centos-7配置靜態ip地址" tabindex="-1">Linux有問必答：如何為CentOS 7配置靜態IP地址 <a class="header-anchor" href="#linux有問必答-如何為centos-7配置靜態ip地址" aria-label="Permalink to “Linux有問必答：如何為CentOS 7配置靜態IP地址”">​</a></h1><blockquote><p><strong>問題</strong>：在CentOS 7上，我想要將我其中一個網絡接口從DHCP改為靜態IP地址配置，如何才能永久為CentOS或RHEL 7上的網絡接口分配靜態IP地址？</p></blockquote><p>如果你想要為CentOS 7中的某個網絡接口設置靜態IP地址，有幾種不同的方法，這取決於你是否想要使用網絡管理器。</p><p>網絡管理器（Network Manager）是一個動態網絡的控制器與配置系統，它用於當網絡設備可用時保持設備和連接開啓並激活。默認情況下，CentOS/RHEL 7安裝有網絡管理器，並處於啓用狀態。</p><p>使用下面的命令來驗證網絡管理器服務的狀態：</p><pre><code>$ systemctl status NetworkManager.service
</code></pre><p>運行以下命令來檢查受網絡管理器管理的網絡接口：</p><pre><code>$ nmcli dev status 
</code></pre><p><img src="https://farm4.staticflickr.com/3861/15295802711_a102a3574d_z.jpg" alt=""></p><p>如果某個接口的nmcli的輸出結果是“已連接”（如本例中的enp0s3），這就是説該接口受網絡管理器管理。你可以輕易地為某個特定接口禁用網絡管理器，以便你可以自己為它配置一個靜態IP地址。</p><p>下面將介紹<strong>在CentOS 7上為網絡接口配置靜態IP地址的兩種方式</strong>，在例子中我們將對名為enp0s3的網絡接口進行配置。</p><h3 id="不使用網絡管理配置靜態ip地址" tabindex="-1">不使用網絡管理配置靜態IP地址 <a class="header-anchor" href="#不使用網絡管理配置靜態ip地址" aria-label="Permalink to “不使用網絡管理配置靜態IP地址”">​</a></h3><p>進入/etc/sysconfig/network-scripts目錄，找到該接口的配置文件（ifcfg-enp0s3）。如果沒有，請創建一個。</p><p><img src="https://farm4.staticflickr.com/3911/15112399977_d3df8e15f5_z.jpg" alt=""></p><p>打開配置文件並編輯以下變量：</p><p><img src="https://farm4.staticflickr.com/3880/15112184199_f4cbf269a6.jpg" alt=""></p><p>在上圖中，“NM_CONTROLLED=no”表示該接口將通過該配置文件進行設置，而不是通過網絡管理器進行管理。“ONBOOT=yes”告訴我們，系統將在啓動時開啓該接口。</p><p>保存修改並使用以下命令來重啓網絡服務：</p><pre><code># systemctl restart network.service
</code></pre><p>現在驗證接口是否配置正確：</p><pre><code># ip add 
</code></pre><p><img src="https://farm6.staticflickr.com/5593/15112397947_ac69a33fb4_z.jpg" alt=""></p><h3 id="使用網絡管理器配置靜態ip地址" tabindex="-1">使用網絡管理器配置靜態IP地址 <a class="header-anchor" href="#使用網絡管理器配置靜態ip地址" aria-label="Permalink to “使用網絡管理器配置靜態IP地址”">​</a></h3><p>如果你想要使用網絡管理器來管理該接口，你可以使用nmtui（網絡管理器文本用户界面），它提供了在終端環境中配置配置網絡管理器的方式。</p><p>在使用nmtui之前，首先要在/etc/sysconfig/network-scripts/ifcfg-enp0s3中設置“NM_CONTROLLED=yes”。</p><p>現在，請按以下方式安裝nmtui。</p><pre><code># yum install NetworkManager-tui
</code></pre><p>然後繼續去編輯enp0s3接口的網絡管理器配置：</p><pre><code># nmtui edit enp0s3 
</code></pre><p>在下面的屏幕中，我們可以手動輸入與/etc/sysconfig/network-scripts/ifcfg-enp0s3中所包含的內容相同的信息。</p><p>使用箭頭鍵在屏幕中導航，按回車選擇值列表中的內容（或填入想要的內容），最後點擊屏幕底部右側的確定按鈕。</p><p><img src="https://farm4.staticflickr.com/3878/15295804521_4165c97828_z.jpg" alt=""></p><p>最後，重啓網絡服務。</p><pre><code># systemctl restart network.service
</code></pre><p>好了，現在一切都搞定了。</p><hr>`,36)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),n(s,{href:"http://ask.xmodulo.com/configure-static-ip-address-centos7.html"},{default:p(()=>[...t[0]||(t[0]=[e("http://ask.xmodulo.com/configure-static-ip-address-centos7.html",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=e("譯者：",-1)),n(s,{href:"https://github.com/GOLinux"},{default:p(()=>[...t[2]||(t[2]=[e("GOLinux",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),n(s,{href:"https://github.com/wxy"},{default:p(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=e("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),n(s,{href:"http://linux.cn/"},{default:p(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const O=i(d,[["render",m]]);export{P as __pageData,O as default};
